using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class SpatialOcclusionRefresh {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||StaticOcclusionCulling.isRunning)throw new Exception("Saved Edit required");string asset="Assets/Afrer_Seconds/01.Scenes/Stage/Level_B5_Circular/OcclusionCullingData.asset";string backup=Path.Combine(Path.GetTempPath(),"Spatial_Occlusion_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".asset");File.Copy(Path.GetFullPath(asset),backup);File.WriteAllText(R+"/Docs/검수/2026-11-08_B5_SpatialRefinement/occlusion_backup.json",JsonConvert.SerializeObject(new{asset,backup}));StaticOcclusionCulling.GenerateInBackground();return new{running=StaticOcclusionCulling.isRunning,backup,policy="Existing solid outer shells only; mixed transparent interior assemblies remain dynamic occludees"};}
 public static object Status(){var result=new{running=StaticOcclusionCulling.isRunning,bytes=StaticOcclusionCulling.umbraDataSize};if(!result.running){var s=SceneManager.GetActiveScene();if(s.isDirty)EditorSceneManager.SaveScene(s);File.WriteAllText(R+"/Docs/검수/2026-11-08_B5_SpatialRefinement/occlusion.json",JsonConvert.SerializeObject(result));}return result;}}
